//! 💳️ DSL owning tests borrow one explicit finite bank through source admission, normal work and paid closure.
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,RetirementDemand,ValueError,retained_clone::{RetainedCloneSource,retained_clone_grant_admits},retirement::{RetireOwned,controlled::ControlledRetirement}};
use semio_framework_value_native_owned::native_decoding::{NativeDecodeControl,NativeDecodeConstructionRecipient};
pub struct Bank{remaining:RetainedCloneGrant,fuel:u64}
impl Bank{
 pub fn new(row:&serde_json::Value)->Self{let n=|key:&str|usize::try_from(row[key].as_u64().expect("explicit finite currency")).unwrap();Self{remaining:RetainedCloneGrant{maximum_items:n("items"),maximum_copy_bytes:n("copyBytes"),maximum_capacity_bytes:n("capacityBytes"),maximum_release_bytes:n("releaseBytes"),maximum_depth:n("depth")},fuel:row["fuel"].as_u64().unwrap()}}
 pub fn grant(&self,body:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:if self.fuel>0{self.remaining.maximum_items.min(1)}else{0},maximum_copy_bytes:self.remaining.maximum_copy_bytes.min(body),..self.remaining}}
 pub fn post(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress,work:u64,heap:(usize,usize)){assert!(p.fits(g));assert!(p.fits(self.remaining));assert!(work<=1,"one original bounded turn, observed {work}");assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));self.remaining.maximum_items=self.remaining.maximum_items.checked_sub(p.copied_items).unwrap();self.remaining.maximum_copy_bytes=self.remaining.maximum_copy_bytes.checked_sub(p.copied_bytes).unwrap();self.remaining.maximum_capacity_bytes=self.remaining.maximum_capacity_bytes.checked_sub(p.retained_capacity_bytes).unwrap();self.remaining.maximum_release_bytes=self.remaining.maximum_release_bytes.checked_sub(p.released_bytes).unwrap();self.fuel=self.fuel.checked_sub(work).expect("finite DSL work bank depleted");}
}
pub fn observe<R>(f:impl FnOnce()->R)->(R,(usize,usize)){let(r,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);assert!(!h.overflowed);(r,(h.requested_bytes,h.released_bytes))}
pub fn source<T:RetireOwned+Sync>(value:T,bank:&mut Bank)->RetainedCloneSource<T>{let mut owner=RetainedCloneSource::admission_owned(value,());let mut output=None;for _ in 0..4096{if owner.terminal_is_empty(){break}let g=bank.grant(4096);let(turn,h)=observe(||if owner.phase()=="ready"{owner.take_output(&mut output,g)}else{owner.advance(g)});let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());bank.post(g,p,turn.work,h);turn.result.unwrap();}assert!(owner.terminal_is_empty(),"source needs its concrete demand {:?}",owner.next_demand());output.expect("funded source output remains caller owned")}
struct Loan{grant:RetainedCloneGrant,issued:bool,accepted:bool,submitted:semio_framework_value::RetainedCloneProgress}
impl NativeDecodeConstructionRecipient for Loan{fn submitted(&self)->semio_framework_value::RetainedCloneProgress{self.submitted}fn grant(&mut self,d:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{assert!(!self.issued);assert!(retained_clone_grant_admits(self.grant,d));self.issued=true;Ok(self.grant)}fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{self.submitted=self.submitted.checked_add(p)?;assert!(!self.accepted);assert!(p.fits(g)&&p.fits(self.grant));assert!(g.maximum_items<=self.grant.maximum_items&&g.maximum_copy_bytes<=self.grant.maximum_copy_bytes&&g.maximum_capacity_bytes<=self.grant.maximum_capacity_bytes&&g.maximum_release_bytes<=self.grant.maximum_release_bytes&&g.maximum_depth<=self.grant.maximum_depth);self.accepted=true;Ok(())}}
pub fn receive<R,E:From<ValueError>>(native:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant,f:impl FnOnce(&mut NativeDecodeControl<'_>)->RetainedWorkOutcome<R,E>)->RetainedWorkOutcome<R,E>{let mut loan=Loan{grant:g,issued:false,accepted:false,submitted:Default::default()};let mut work=0;let result=native.with_construction_recipient(&mut loan,|native|{let turn=f(native);work=turn.work;turn.result});RetainedWorkOutcome{result,work}}
pub fn close<T:RetireOwned>(value:T,bank:&mut Bank){let(mut owner,h)=observe(||ControlledRetirement::new(value).unwrap_or_else(|_|panic!("DSL fixture has genuine original retirement")));assert_eq!(h,(0,0));for _ in 0..10000{if owner.terminal_is_empty(){return}let d=owner.next_demand(4096).unwrap();assert!(d.copy_bytes<=4096);let g=bank.grant(4096);let(result,h)=observe(||owner.step(g));let work=owner.last_turn_work();let p=result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());bank.post(g,p,work,h);result.unwrap();}panic!("DSL fixture did not close under its original bound")}
pub fn denied(g:RetainedCloneGrant,d:RetirementDemand)->impl Iterator<Item=RetainedCloneGrant>{[(true,RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0,RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.release_bytes>0,RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}),(d.depth>0,RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})].into_iter().filter_map(|(yes,g)|yes.then_some(g))}
